import { prefersReducedMotion, readDurationMs } from "@/components/control-ui/lib/motion";

const running = new WeakMap<HTMLElement, Animation>();

export function foldPanel(root: HTMLElement | null, panel: HTMLElement | null, apply: () => void) {
  const duration = panel && !prefersReducedMotion(panel) ? readDurationMs(panel, "--duration-slow") : 0;
  if (!root || !panel || duration <= 0) {
    apply();
    return;
  }
  const before = panel.getBoundingClientRect().height;
  running.get(panel)?.cancel();
  root.removeAttribute("data-folding");
  apply();
  const after = panel.getBoundingClientRect().height;
  if (Math.abs(before - after) < 0.5) return;
  root.setAttribute("data-folding", "");
  const easing = getComputedStyle(panel).getPropertyValue("--ease-emphasized").trim() || "ease";
  const animation = panel.animate({ blockSize: [`${before}px`, `${after}px`] }, { duration, easing });
  running.set(panel, animation);
  const settle = () => {
    if (running.get(panel) !== animation) return;
    running.delete(panel);
    root.removeAttribute("data-folding");
  };
  animation.finished.then(settle, settle);
}

"use client";

import type { ComponentProps, KeyboardEvent, PointerEvent as ReactPointerEvent, WheelEvent } from "react";
import { useEffect, useRef } from "react";
import { useChatWorkspace, useChatWorkspaceElements } from "@/components/control-ui/chat-workspace-state";
import { cn } from "@/components/control-ui/lib/cn";

const DRAG_THRESHOLD_PX = 5;
const KEYBOARD_STEP_PX = 16;
const KEYBOARD_LARGE_STEP_PX = 64;
const RESIZE_SHIELD_STAMP = { "data-control-ui": "chat-workspace", "data-control-family": "chat-workspace", "data-slot": "resize-shield" };

export type ChatWorkspaceResizeHandleProps = Omit<
  ComponentProps<"div">,
  "role" | "aria-orientation" | "aria-valuenow" | "aria-valuemin" | "aria-valuemax" | "aria-controls"
>;

function scrollWhatLiesBeneath(event: WheelEvent<HTMLDivElement>) {
  const beneath = document.elementsFromPoint(event.clientX, event.clientY).find((element) => !event.currentTarget.contains(element));
  beneath?.closest("[data-scroll-area-viewport]")?.scrollBy({ left: event.deltaX, top: event.deltaY });
}

export function ChatWorkspaceResizeHandle({
  className,
  onPointerDown,
  onKeyDown,
  onWheel,
  "aria-label": ariaLabel = "Resize chat panel",
  ...props
}: ChatWorkspaceResizeHandleProps) {
  const { presentation, side, panelId, panelWidth, minPanelWidth, maxPanelWidth, setPanelWidth, clampPanelWidth } = useChatWorkspace();
  const { panelRef } = useChatWorkspaceElements();
  const cancelGestureRef = useRef<(() => void) | null>(null);

  useEffect(() => () => cancelGestureRef.current?.(), []);

  if (presentation !== "docked") return null;

  const widenSign = side === "right" ? -1 : 1;

  function startGesture(event: ReactPointerEvent<HTMLDivElement>) {
    onPointerDown?.(event);
    const panel = panelRef.current;
    if (event.defaultPrevented || event.button !== 0 || !panel) return;
    event.preventDefault();
    cancelGestureRef.current?.();
    const handle = event.currentTarget;
    handle.focus({ preventScroll: true, focusVisible: false });
    handle.setPointerCapture(event.pointerId);
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const startWidth = panel.getBoundingClientRect().width;
    const shield = document.createElement("div");
    for (const [name, value] of Object.entries(RESIZE_SHIELD_STAMP)) shield.setAttribute(name, value);
    const controller = new AbortController();
    let dragged = false;
    let draftWidth = startWidth;

    function endGesture() {
      controller.abort();
      shield.remove();
      handle.removeAttribute("data-resizing");
      if (handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
      cancelGestureRef.current = null;
    }

    function cancelGesture() {
      endGesture();
      if (dragged && panel) panel.style.inlineSize = `${startWidth}px`;
    }
    cancelGestureRef.current = cancelGesture;

    function dragging(pointer: PointerEvent) {
      if (dragged) return true;
      if (Math.abs(pointer.clientX - startX) <= DRAG_THRESHOLD_PX) return false;
      dragged = true;
      document.body.append(shield);
      handle.setAttribute("data-resizing", "");
      return true;
    }

    function movePointer(pointer: PointerEvent) {
      if (pointer.pointerId !== pointerId || !dragging(pointer) || !panel) return;
      draftWidth = clampPanelWidth(startWidth + widenSign * (pointer.clientX - startX));
      panel.style.inlineSize = `${draftWidth}px`;
    }

    function finishPointer(pointer: PointerEvent) {
      if (pointer.pointerId !== pointerId) return;
      endGesture();
      if (dragged) setPanelWidth(draftWidth);
    }

    function cancelPointer(pointer: PointerEvent) {
      if (pointer.pointerId === pointerId) cancelGesture();
    }

    function cancelWithEscape(keyboard: globalThis.KeyboardEvent) {
      if (keyboard.key !== "Escape") return;
      keyboard.preventDefault();
      cancelGesture();
    }

    window.addEventListener("pointermove", movePointer, { signal: controller.signal });
    window.addEventListener("pointerup", finishPointer, { signal: controller.signal });
    window.addEventListener("pointercancel", cancelPointer, { signal: controller.signal });
    handle.addEventListener("lostpointercapture", cancelPointer, { signal: controller.signal });
    window.addEventListener("blur", cancelGesture, { signal: controller.signal });
    window.addEventListener("keydown", cancelWithEscape, { signal: controller.signal });
  }

  function keyboardWidth(event: KeyboardEvent<HTMLDivElement>) {
    const step = event.shiftKey ? KEYBOARD_LARGE_STEP_PX : KEYBOARD_STEP_PX;
    if (event.key === "ArrowLeft") return panelWidth - widenSign * step;
    if (event.key === "ArrowRight") return panelWidth + widenSign * step;
    if (event.key === "Home") return minPanelWidth;
    if (event.key === "End") return maxPanelWidth;
    return undefined;
  }

  function resizeWithKeyboard(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    const next = keyboardWidth(event);
    if (next === undefined) return;
    event.preventDefault();
    setPanelWidth(clampPanelWidth(next));
  }

  return (
    // biome-ignore lint/a11y/useSemanticElements: focusable window splitter needs pointer and key handlers an <hr> cannot carry
    <div
      {...props}
      role="separator"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-orientation="vertical"
      aria-controls={panelId}
      aria-valuenow={panelWidth}
      aria-valuemin={minPanelWidth}
      aria-valuemax={maxPanelWidth}
      data-control-ui="chat-workspace"
      data-control-family="chat-workspace"
      data-slot="resize-handle"
      className={cn("absolute inset-y-0 touch-none select-none", className)}
      onPointerDown={startGesture}
      onKeyDown={resizeWithKeyboard}
      onWheel={(event) => {
        onWheel?.(event);
        if (!event.defaultPrevented) scrollWhatLiesBeneath(event);
      }}
    />
  );
}

"use client";

import type { RefObject } from "react";
import { createContext, useContext, useState } from "react";

export type ChatWorkspaceSide = "left" | "right";

export type ChatWorkspacePresentation = "floating" | "docked";

export type ChatWorkspaceContextValue = {
  docked: boolean;
  presentation: ChatWorkspacePresentation;
  canDock: boolean;
  expanded: boolean;
  side: ChatWorkspaceSide;
  panelWidth: number;
  minPanelWidth: number;
  maxPanelWidth: number;
  minMainWidth: number;
  panelId: string;
  collapsibleId: string;
  setDocked: (docked: boolean) => void;
  setExpanded: (expanded: boolean) => void;
  setPanelWidth: (width: number) => void;
  clampPanelWidth: (width: number) => number;
};

export type ChatWorkspaceElements = {
  rootRef: RefObject<HTMLDivElement | null>;
  mainRef: RefObject<HTMLDivElement | null>;
  panelRef: RefObject<HTMLElement | null>;
  registerPanel: (panel: HTMLElement | null) => void;
  registerInset: (inset: HTMLDivElement | null) => void;
};

export const ChatWorkspaceContext = createContext<ChatWorkspaceContextValue | null>(null);

export const ChatWorkspaceElementsContext = createContext<ChatWorkspaceElements | null>(null);

export function useChatWorkspace(): ChatWorkspaceContextValue {
  const workspace = useContext(ChatWorkspaceContext);
  if (!workspace) throw new Error("useChatWorkspace() must be called inside <ChatWorkspace>.");
  return workspace;
}

export function useChatWorkspaceElements(): ChatWorkspaceElements {
  const elements = useContext(ChatWorkspaceElementsContext);
  if (!elements) throw new Error("ChatWorkspace parts must be rendered inside <ChatWorkspace>.");
  return elements;
}

export function useControllableState<T>(controlled: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const value = controlled ?? uncontrolled;
  function setValue(next: T) {
    if (controlled === undefined) setUncontrolled(next);
    onChange?.(next);
  }
  return [value, setValue] as const;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), Math.max(min, max));
}

"use client";

import { ChevronDown, PanelLeft, PanelRight, PictureInPicture2 } from "lucide-react";
import type { ComponentProps, CSSProperties, MouseEvent, RefObject } from "react";
import { useCallback, useId, useLayoutEffect, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { foldPanel } from "@/components/control-ui/chat-workspace-fold";
import {
  ChatWorkspaceContext,
  type ChatWorkspaceContextValue,
  ChatWorkspaceElementsContext,
  type ChatWorkspaceSide,
  clamp,
  useChatWorkspace,
  useChatWorkspaceElements,
  useControllableState,
} from "@/components/control-ui/chat-workspace-state";
import { startMorphViewTransition } from "@/components/control-ui/extensions/view-transition";
import { cn } from "@/components/control-ui/lib/cn";
import { useSkinIcon } from "@/components/control-ui/skin-provider";
import { Button, type ButtonProps } from "@/components/control-ui/ui/button";

// biome-ignore lint/performance/noBarrelFile: The workspace exposes one install-facing API across its split files.
export { ChatWorkspaceResizeHandle, type ChatWorkspaceResizeHandleProps } from "@/components/control-ui/chat-workspace-resize-handle";
export {
  type ChatWorkspaceContextValue,
  type ChatWorkspacePresentation,
  type ChatWorkspaceSide,
  useChatWorkspace,
} from "@/components/control-ui/chat-workspace-state";

const DEFAULT_PANEL_WIDTH = 384;
const DEFAULT_MIN_PANEL_WIDTH = 288;
const DEFAULT_MAX_PANEL_WIDTH = 640;
const DEFAULT_MIN_MAIN_WIDTH = 320;
const MORPH_CLASS = "aui-morph";
const MORPH_NAME = "cui-chat-workspace";

export type ChatWorkspaceProps = ComponentProps<"div"> & {
  side?: ChatWorkspaceSide;
  docked?: boolean;
  defaultDocked?: boolean;
  onDockedChange?: (docked: boolean) => void;
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  panelWidth?: number;
  defaultPanelWidth?: number;
  onPanelWidthChange?: (width: number) => void;
  minPanelWidth?: number;
  maxPanelWidth?: number;
  /** Narrowest the main content may get beside a pinned panel; below it the panel floats instead. */
  minMainWidth?: number;
};

function useFits(rootRef: RefObject<HTMLDivElement | null>, required: number) {
  const [fits, setFits] = useState(true);
  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const measure = () => setFits(root.clientWidth >= required);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    return () => observer.disconnect();
  }, [rootRef, required]);
  return fits;
}

function useInsets(rootRef: RefObject<HTMLDivElement | null>, panel: HTMLElement | null, docked: boolean) {
  const insetsRef = useRef(new Set<HTMLDivElement>());
  const updateRef = useRef(() => {});

  useLayoutEffect(() => {
    updateRef.current = () => {
      const root = rootRef.current;
      let size = 0;
      if (root && panel && !docked) {
        const gap = Number.parseFloat(getComputedStyle(panel).marginBlockEnd) || 0;
        size = Math.max(0, root.getBoundingClientRect().bottom - panel.getBoundingClientRect().top + gap);
      }
      for (const inset of insetsRef.current) inset.style.blockSize = `${size}px`;
    };
    updateRef.current();
  }, [rootRef, panel, docked]);

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const observer = new ResizeObserver(() => updateRef.current());
    observer.observe(root);
    if (panel) observer.observe(panel);
    return () => observer.disconnect();
  }, [rootRef, panel]);

  return useCallback((inset: HTMLDivElement | null) => {
    if (!inset) return;
    insetsRef.current.add(inset);
    updateRef.current();
    return () => {
      insetsRef.current.delete(inset);
    };
  }, []);
}

function useMorph(elements: { panelRef: RefObject<HTMLElement | null>; mainRef: RefObject<HTMLDivElement | null> }) {
  const token = useId().replace(/[^a-zA-Z0-9]/g, "");
  const activeRef = useRef<ViewTransition | undefined>(undefined);

  function name(named: boolean) {
    const parts = [
      [elements.panelRef.current, `${MORPH_NAME}-panel-${token}`],
      [elements.mainRef.current, `${MORPH_NAME}-main-${token}`],
    ] as const;
    for (const [element, value] of parts) {
      if (!element) continue;
      element.style.viewTransitionName = named ? value : "";
      element.style.setProperty("view-transition-class", named ? MORPH_CLASS : "");
    }
  }

  return function morph(update: () => void) {
    name(true);
    const transition = startMorphViewTransition(() => flushSync(update));
    activeRef.current = transition;
    if (!transition) {
      name(false);
      return;
    }
    transition.finished
      .catch(() => {})
      .finally(() => {
        if (activeRef.current !== transition) return;
        activeRef.current = undefined;
        name(false);
      });
  };
}

export function ChatWorkspace({
  side = "right",
  docked: dockedProp,
  defaultDocked = false,
  onDockedChange,
  expanded: expandedProp,
  defaultExpanded = true,
  onExpandedChange,
  panelWidth: panelWidthProp,
  defaultPanelWidth = DEFAULT_PANEL_WIDTH,
  onPanelWidthChange,
  minPanelWidth = DEFAULT_MIN_PANEL_WIDTH,
  maxPanelWidth = DEFAULT_MAX_PANEL_WIDTH,
  minMainWidth = DEFAULT_MIN_MAIN_WIDTH,
  className,
  children,
  ...props
}: ChatWorkspaceProps) {
  const [docked, setDockedState] = useControllableState(dockedProp, defaultDocked, onDockedChange);
  const [requestedExpanded, setExpanded] = useControllableState(expandedProp, defaultExpanded, onExpandedChange);
  const [requestedWidth, setRequestedWidth] = useControllableState(panelWidthProp, defaultPanelWidth, onPanelWidthChange);
  const rootRef = useRef<HTMLDivElement>(null);
  const mainRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLElement>(null);
  const [panel, setPanel] = useState<HTMLElement | null>(null);
  const registerPanel = useCallback((element: HTMLElement | null) => {
    panelRef.current = element;
    setPanel(element);
  }, []);
  const panelId = useId();
  const collapsibleId = useId();

  const canDock = useFits(rootRef, minMainWidth + minPanelWidth);
  const presentation = docked && canDock ? "docked" : "floating";
  const registerInset = useInsets(rootRef, panel, presentation === "docked");
  const morph = useMorph({ panelRef, mainRef });
  const expanded = presentation === "docked" || requestedExpanded;

  function clampPanelWidth(width: number) {
    const room = rootRef.current ? rootRef.current.clientWidth - minMainWidth : maxPanelWidth;
    return Math.round(clamp(width, minPanelWidth, Math.min(maxPanelWidth, room)));
  }

  const workspace: ChatWorkspaceContextValue = {
    docked,
    presentation,
    canDock,
    expanded,
    side,
    panelWidth: Math.round(clamp(requestedWidth, minPanelWidth, maxPanelWidth)),
    minPanelWidth,
    maxPanelWidth,
    minMainWidth,
    panelId,
    collapsibleId,
    setDocked: (next) => {
      if (next === docked) return;
      morph(() => setDockedState(next));
    },
    setExpanded: (next) => foldPanel(rootRef.current, panelRef.current, () => flushSync(() => setExpanded(next))),
    setPanelWidth: (width) => setRequestedWidth(clamp(width, minPanelWidth, maxPanelWidth)),
    clampPanelWidth,
  };

  return (
    <ChatWorkspaceContext.Provider value={workspace}>
      <ChatWorkspaceElementsContext.Provider value={{ rootRef, mainRef, panelRef, registerPanel, registerInset }}>
        <div
          {...props}
          ref={rootRef}
          data-control-ui="chat-workspace"
          data-control-family="chat-workspace"
          data-slot="root"
          data-side={side}
          data-docked={presentation === "docked" ? "" : undefined}
          data-expanded={expanded ? "" : undefined}
          className={cn("relative grid min-h-0 min-w-0", className)}
        >
          {children}
        </div>
      </ChatWorkspaceElementsContext.Provider>
    </ChatWorkspaceContext.Provider>
  );
}

export type ChatWorkspaceMainProps = ComponentProps<"div">;

export function ChatWorkspaceMain({ className, ...props }: ChatWorkspaceMainProps) {
  const { mainRef } = useChatWorkspaceElements();
  return (
    <div
      {...props}
      ref={mainRef}
      data-control-ui="chat-workspace"
      data-control-family="chat-workspace"
      data-slot="main"
      className={cn("min-h-0 min-w-0", className)}
    />
  );
}

export type ChatWorkspacePanelProps = Omit<ComponentProps<"aside">, "id">;

export function ChatWorkspacePanel({ className, style, "aria-label": ariaLabel = "Chat", ...props }: ChatWorkspacePanelProps) {
  const { panelId, panelWidth, minMainWidth, presentation } = useChatWorkspace();
  const { registerPanel } = useChatWorkspaceElements();
  const sized: CSSProperties | undefined =
    presentation === "docked" ? { ...style, inlineSize: `${panelWidth}px`, maxInlineSize: `calc(100cqi - ${minMainWidth}px)` } : style;
  return (
    <aside
      {...props}
      ref={registerPanel}
      id={panelId}
      aria-label={ariaLabel}
      data-control-ui="chat-workspace"
      data-control-family="chat-workspace"
      data-slot="panel"
      className={cn("relative flex min-h-0 min-w-0 flex-col", className)}
      style={sized}
    />
  );
}

export type ChatWorkspaceInsetProps = Omit<ComponentProps<"div">, "children">;

/** Spacer for the end of the main content's scroller, so its last lines can scroll clear of the floating panel. */
export function ChatWorkspaceInset({ className, ...props }: ChatWorkspaceInsetProps) {
  const { registerInset } = useChatWorkspaceElements();
  return (
    <div
      {...props}
      ref={registerInset}
      aria-hidden="true"
      data-control-ui="chat-workspace"
      data-control-family="chat-workspace"
      data-slot="inset"
      className={cn("pointer-events-none shrink-0", className)}
    />
  );
}

export type ChatWorkspaceCollapsibleProps = Omit<ComponentProps<"div">, "id">;

export function ChatWorkspaceCollapsible({ className, ...props }: ChatWorkspaceCollapsibleProps) {
  const { collapsibleId, expanded } = useChatWorkspace();
  return (
    <div
      {...props}
      id={collapsibleId}
      inert={!expanded}
      data-control-ui="chat-workspace"
      data-control-family="chat-workspace"
      data-slot="collapsible"
      className={cn("grid min-h-0 min-w-0", className)}
    />
  );
}

export type ChatWorkspaceExpandToggleProps = Omit<ButtonProps, "aria-expanded" | "aria-controls">;

export function ChatWorkspaceExpandToggle({
  onClick,
  children,
  "aria-label": ariaLabel = "Conversation",
  ...props
}: ChatWorkspaceExpandToggleProps) {
  const ChevronDownGlyph = useSkinIcon("chevronDown", ChevronDown);
  const { collapsibleId, expanded, presentation, setExpanded } = useChatWorkspace();
  if (presentation === "docked") return null;
  function toggle(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    if (!event.defaultPrevented) setExpanded(!expanded);
  }
  return (
    <Button
      variant="ghost"
      size="sm"
      iconOnly
      {...props}
      type="button"
      aria-label={ariaLabel}
      aria-expanded={expanded}
      aria-controls={collapsibleId}
      onClick={toggle}
    >
      {children ?? <ChevronDownGlyph aria-hidden="true" data-control-family="chat-workspace" data-slot="expand-icon" />}
    </Button>
  );
}

export type ChatWorkspaceDockToggleProps = Omit<ButtonProps, "aria-label"> & {
  pinLabel?: string;
  floatLabel?: string;
};

export function ChatWorkspaceDockToggle({
  onClick,
  children,
  pinLabel = "Pin to side",
  floatLabel = "Float",
  ...props
}: ChatWorkspaceDockToggleProps) {
  const { docked, canDock, side, setDocked } = useChatWorkspace();
  const PanelLeftGlyph = useSkinIcon("panelLeft", PanelLeft);
  const PanelRightGlyph = useSkinIcon("panelRight", PanelRight);
  const PictureInPictureGlyph = useSkinIcon("pictureInPicture", PictureInPicture2);
  if (!canDock) return null;
  const PinGlyph = side === "left" ? PanelLeftGlyph : PanelRightGlyph;
  function toggle(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    if (!event.defaultPrevented) setDocked(!docked);
  }
  return (
    <Button variant="ghost" size="sm" iconOnly {...props} type="button" aria-label={docked ? floatLabel : pinLabel} onClick={toggle}>
      {children ?? (docked ? <PictureInPictureGlyph aria-hidden="true" /> : <PinGlyph aria-hidden="true" />)}
    </Button>
  );
}

@layer components {
  :where([data-control-family="chat-workspace"][data-slot="root"]) {
    --cui-chat-workspace-gap: calc(var(--spacing) * 3);
    --cui-chat-workspace-island-max-inline-size: 44rem;
    --cui-chat-workspace-transcript-block-size: 28rem;
    --cui-chat-workspace-background: var(--card);
    --cui-chat-workspace-foreground: var(--card-foreground);
    --cui-chat-workspace-border-color: var(--border);
    --cui-chat-workspace-border-width: var(--control-rim-width);
    --cui-chat-workspace-radius: max(
      var(--radius-panel),
      calc(var(--radius-composer) + var(--composer-padding) + var(--cui-chat-workspace-border-width))
    );
    --cui-chat-workspace-shadow: var(--shadow-pop);
    --cui-chat-workspace-handle-background: oklch(from var(--foreground) l c h / 0.3);
    container-type: inline-size;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
  }

  :where([data-control-family="chat-workspace"][data-slot="main"]) {
    grid-area: 1 / 1;
  }

  :where([data-control-family="chat-workspace"][data-slot="panel"]) {
    z-index: var(--z-raised);
    grid-area: 1 / 1;
    align-self: end;
    justify-self: center;
    inline-size: min(var(--cui-chat-workspace-island-max-inline-size), 100% - var(--cui-chat-workspace-gap) * 2);
    max-block-size: calc(100% - var(--cui-chat-workspace-gap) * 2);
    margin-block-end: var(--cui-chat-workspace-gap);
    overflow: hidden;
    border: var(--cui-chat-workspace-border-width) solid var(--cui-chat-workspace-border-color);
    border-radius: var(--cui-chat-workspace-radius);
    background-color: var(--cui-chat-workspace-background);
    color: var(--cui-chat-workspace-foreground);
    box-shadow: var(--cui-chat-workspace-shadow);
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-docked]) {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-docked][data-side="left"]) {
    grid-template-columns: auto minmax(0, 1fr);
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-docked][data-side="left"] > [data-slot="main"]) {
    grid-column: 2;
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-docked] > [data-slot="panel"]) {
    grid-column: 2;
    align-self: stretch;
    justify-self: stretch;
    max-block-size: none;
    margin: 0;
    border-block-width: 0;
    border-inline-end-width: 0;
    border-radius: 0;
    box-shadow: none;
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-docked][data-side="left"] > [data-slot="panel"]) {
    grid-column: 1;
    border-inline-start-width: 0;
    border-inline-end-width: var(--cui-chat-workspace-border-width);
  }

  :where([data-control-family="chat-workspace"][data-slot="collapsible"]) {
    display: contents;
  }

  :where(
    [data-control-family="chat-workspace"][data-slot="root"]:not([data-docked])
      > [data-slot="panel"]
      [data-control-family="chat-layout"][data-chat-layout-kind="thread"][data-slot="root"]
  ) {
    max-block-size: var(--cui-chat-workspace-transcript-block-size);
  }

  :where([data-control-family="chat-workspace"][data-slot="expand-icon"]) {
    transition: rotate var(--duration-base) var(--ease-emphasized);
  }

  :where([data-control-family="chat-workspace"][data-slot="root"]:not([data-expanded]) [data-slot="expand-icon"]) {
    rotate: 180deg;
  }

  :where([data-control-family="chat-workspace"][data-slot="resize-handle"]) {
    --_chat-workspace-handle-color: transparent;
    z-index: 1;
    inline-size: calc(var(--spacing) * 2);
    cursor: col-resize;
    outline: none;
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-side="right"] [data-slot="resize-handle"]) {
    left: 0;
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-side="left"] [data-slot="resize-handle"]) {
    right: 0;
  }

  :where([data-control-family="chat-workspace"][data-slot="resize-handle"])::after {
    content: "";
    position: absolute;
    inset-block: 0;
    inline-size: max(1px, var(--cui-chat-workspace-border-width));
    background-color: var(--_chat-workspace-handle-color);
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-side="right"] [data-slot="resize-handle"])::after {
    left: 0;
  }

  :where([data-control-family="chat-workspace"][data-slot="root"][data-side="left"] [data-slot="resize-handle"])::after {
    right: 0;
  }

  @media (hover: hover) {
    :where([data-control-family="chat-workspace"][data-slot="resize-handle"]:hover) {
      --_chat-workspace-handle-color: var(--cui-chat-workspace-handle-background);
    }
  }

  :where([data-control-family="chat-workspace"][data-slot="resize-handle"][data-resizing]) {
    --_chat-workspace-handle-color: var(--cui-chat-workspace-handle-background);
  }

  :where([data-control-family="chat-workspace"][data-slot="resize-handle"]:focus-visible) {
    --_chat-workspace-handle-color: var(--focus-ring);
  }

  :where([data-control-family="chat-workspace"][data-slot="resize-shield"]) {
    position: fixed;
    inset: 0;
    z-index: var(--z-tooltip);
    cursor: col-resize;
    user-select: none;
  }

  @media (prefers-reduced-motion: reduce) {
    :where([data-control-family="chat-workspace"][data-slot="expand-icon"]) {
      transition: none;
    }
  }
